<?php
declare(strict_types=1);require_once __DIR__.'/billing_common.php';$user=billing_require_admin();production_require_method('GET');accounts_endpoint(function():array{$db=production_db();$where=[];$args=[];if(($c=(int)($_GET['client_id']??0))>0){$where[]='i.client_id=?';$args[]=$c;}$sql="SELECT i.*,COALESCE((SELECT SUM(a.cash_amount+a.wht_amount) FROM qbook_customer_receipt_allocations a JOIN qbook_customer_receipts r ON r.id=a.receipt_id AND r.status='POSTED' WHERE a.invoice_id=i.id),0)+COALESCE((SELECT SUM(a.amount) FROM qbook_advance_applications a WHERE a.invoice_id=i.id),0)+COALESCE((SELECT SUM(ca.amount) FROM qbook_credit_note_allocations ca JOIN qbook_credit_notes c ON c.id=ca.credit_note_id AND c.status='ISSUED' WHERE ca.invoice_id=i.id),0) settled FROM qbook_invoices i".($where?' WHERE '.implode(' AND ',$where):'')." ORDER BY COALESCE(i.invoice_date,DATE(i.created_at)) DESC,i.id DESC";$s=$db->prepare($sql);$s->execute($args);$out=[];foreach($s->fetchAll()as$r){$total=$r['total_amount']===null?0:accounts_money_minor($r['total_amount'],false);$settled=accounts_money_minor((string)$r['settled'],false);$r['reference']=billing_ref('INVOICE',$r['reference_no']);$r['outstanding']=accounts_minor_decimal($total-$settled);$r['display_status']=billing_display_status($r+['outstanding_minor'=>$total-$settled]);$out[]=$r;}return['invoices'=>$out];});
